                            element=inp,
                            required=required
                        ))
                except Exception:
                    continue

            # 4. Textareas
            textareas = await target.locator("textarea").all()
            for ta in textareas:
                try:
                    label_text = await self._get_label_for(ta, target)

                    if label_text:
                        required = await ta.get_attribute("required") is not None

                        questions.append(Question(
                            text=label_text,
                            type="textarea",
                            element=ta,
                            required=required
                        ))
                except Exception:
                    continue

            # 5. Checkbox groups
